 a=r['audit'];g=a['separation']['ensemble_mean'];m=a['separation']['pooled_members'];lines.append(f"| {name} | {span(m['normal_range'])} | {span(m['pseudo_range'])} | {span(m['overlap_interval']) if m['overlap_interval'] else 'none'} | {f(g['gap'])} | {f(g['best_threshold'])} | {g['violations']}/{r['CAL_normal_rows']+r['CAL_pseudo_rows']} |")
