 for label in ['normal','pseudo']:
  old_d=c['two_scenario']['raw_score_distributions'][label]['ensemble_mean'];new_d=c['ten_scenario']['raw_score_distributions'][label]['ensemble_mean']
  lines.append(f"| {name} / {label} | {f(old_d['p10'])}/{f(old_d['median'])}/{f(old_d['p90'])} | {f(new_d['p10'])}/{f(new_d['median'])}/{f(new_d['p90'])} |")
